1	"use client";
2	
3	import { AnimatePresence, motion } from "motion/react";
4	import { useEffect, useState, useSyncExternalStore } from "react";
5	import { Emblem } from "./brand/Logo";
6	import type { MapHandle, IntroStep } from "./map/MapView";
7	import type { CoverArt } from "@/lib/brandAssets";
8	import { EASE_OUT } from "@/lib/motion";
9	
10	type Props = {
11	  map: React.RefObject<MapHandle | null>;
12	  mapState: "loading" | "ready" | "unavailable";
13	  reason?: string;
14	  onDone: () => void;
15	  cover?: CoverArt;
16	};
17	
18	const REASONS: Record<string, string> = {
19	  "missing-token": "Map token isn't configured for this deployment.",
20	  "bad-token": "The map token was rejected.",
21	  webgl: "This device can't draw the 3D map.",
22	};
23	
24	const TIPS = [
25	  "Walk anywhere in London to clear the fog.",
26	  "Tap a neighbourhood to see how much of it you own.",
27	  "Missions from The Goose pay Rep. Rep raises your rank.",
28	  "Your location is never shared live. Only cleared fog.",
29	  "Leave tags for whoever clears the fog after you.",
30	];
31	
32	const CAPTIONS: Record<Exclude<IntroStep, "done">, { kicker: string; title: string }> = {
33	  forest: { kicker: "Welcome to", title: "Forest State" },
34	  mustang: { kicker: "Western campus", title: "Mustang City" },
35	};
36	
37	const SEEN_KEY = "mc.intro.seen";
38	const noopSubscribe = () => () => {};
39	const seenThisSession = () => {
40	  try {
41	    return sessionStorage.getItem(SEEN_KEY) === "1";
42	  } catch {
43	    return false;
44	  }
45	};
46	
47	/**
48	 * Entrance: branded loader → "tap to enter" title card → letterboxed camera flight from the whole
49	 * of Forest State down into Mustang City, with establishing-shot captions. Once per session;
50	 * later loads just fade the loader. The tap also gives us the user gesture audio needs later.
51	 */
52	export default function Intro({ map, mapState, reason, onDone, cover = null }: Props) {
53	  const seen = useSyncExternalStore(noopSubscribe, seenThisSession, () => false);
54	  const [chosen, setPhase] = useState<"title" | "flying" | "done" | null>(null);
55	  const phase = mapState !== "ready" ? "loader" : (chosen ?? (seen ? "done" : "title"));
56	  const [caption, setCaption] = useState<IntroStep | null>(null);
57	  const [tip, setTip] = useState(0);
58	
59	  useEffect(() => {
60	    if (phase !== "loader" && phase !== "title") return;
61	    const t = setInterval(() => setTip((i) => (i + 1) % TIPS.length), 2600);
62	    return () => clearInterval(t);
63	  }, [phase]);
64	
65	  useEffect(() => {
66	    if (phase === "title") map.current?.prepareIntro();
67	    if (phase === "done") onDone();
68	  }, [phase, map, onDone]);
69	
70	  // Replay from the demo panel.
71	  useEffect(() => {
72	    const replay = () => setPhase("title");
73	    window.addEventListener("mc:replay-intro", replay);
74	    return () => window.removeEventListener("mc:replay-intro", replay);
75	  }, [map]);
76	
77	  async function enter() {
78	    try {
79	      sessionStorage.setItem(SEEN_KEY, "1");
80	    } catch {
81	      /* private mode: the intro just plays again next time */
82	    }
83	    setPhase("flying");
84	    await map.current?.playIntro(setCaption);
85	    setCaption(null);
86	    setPhase("done");
87	    onDone();
88	  }
89	
90	  const cap = caption && caption !== "done" ? CAPTIONS[caption] : null;
91	
92	  return (
93	    <>
94	      {/* Loader + title card: genre-style loading art (our own 3D campus at dusk), slowly panning and cross-fading */}
95	      <AnimatePresence>
96	        {(phase === "loader" || phase === "title") && (
97	          <motion.div
98	            key="loader"
99	            className="absolute inset-0 z-[45] overflow-hidden bg-[#0c0618]"
100	            initial={{ opacity: 1 }}
101	            exit={{ opacity: 0, scale: 1.04 }}
102	            transition={{ duration: 0.8, ease: EASE_OUT }}
103	          >
104	            {cover ? <CoverArtLayer cover={cover} /> : <Postcards />}
105	            {/* legibility: soft top + strong bottom gradient */}
106	            <div aria-hidden className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-[#0c0618]/70 to-transparent" />
107	            <div aria-hidden className="absolute inset-x-0 bottom-0 h-[58%] bg-gradient-to-t from-[#0c0618] via-[#0c0618]/85 to-transparent" />
108	
109	            <div className="absolute inset-x-6 flex flex-col" style={{ bottom: "calc(var(--safe-bottom) + 34px)" }}>
110	              <motion.div initial={{ y: 14, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ duration: 0.9, ease: EASE_OUT }}>
111	                <div className="flex items-end gap-3">
112	                  <Emblem size={64} />
113	                  <div className="pb-1">
114	                    <p className="mb-1.5 text-[12px] font-semibold tracking-[0.3em] text-teal uppercase">Forest State</p>
115	                    <p
116	                      className="font-display text-[54px] leading-[0.86] uppercase"
117	                      style={{
118	                        background: "linear-gradient(180deg, #ffe3a3 0%, #ffb35c 35%, #ff7a59 62%, #ff4f8b 100%)",
119	                        WebkitBackgroundClip: "text",
120	                        backgroundClip: "text",
121	                        color: "transparent",
122	                      }}
123	                    >
124	                      Mustang City
125	                    </p>
126	                  </div>
127	                </div>
128	              </motion.div>
129	
130	              {mapState === "unavailable" ? (
131	                <div className="glass mt-6 rounded-[20px] px-5 py-4">
132	                  <p className="text-[16px] font-semibold text-ink">Map unavailable</p>
133	                  <p className="mt-1 text-[14px] text-ink/70">{REASONS[reason ?? ""] ?? "Something went wrong loading the map."}</p>
134	                </div>
135	              ) : phase === "title" ? (
136	                <motion.button
137	                  type="button"
138	                  onClick={enter}
139	                  initial={{ opacity: 0, y: 10 }}
140	                  animate={{ opacity: 1, y: 0 }}
141	                  transition={{ duration: 0.5, ease: EASE_OUT }}
142	                  className="btn-sunset mt-7 flex min-h-[56px] w-full items-center justify-center rounded-full text-[16px] font-bold"
143	                >
144	                  Tap to enter
145	                </motion.button>
146	              ) : (
147	                <div className="mt-7 flex min-h-[56px] items-center justify-between gap-4">
148	                  <p key={tip} className="max-w-[78%] animate-[fadein_400ms_ease-out] text-[14px] leading-snug text-ink/75">
149	                    {TIPS[tip]}
150	                  </p>
151	                  <span className="h-6 w-6 shrink-0 animate-spin rounded-full border-2 border-white/15 border-t-gold" aria-label="Loading" />
152	                </div>
153	              )}
154	              {phase === "title" && (
155	                <p key={tip} className="mt-3 h-9 animate-[fadein_400ms_ease-out] text-center text-[12px] leading-snug text-ink/60">
156	                  {TIPS[tip]}
157	                </p>
158	              )}
159	            </div>
160	          </motion.div>
161	        )}
162	      </AnimatePresence>
163	
164	      {/* Letterbox + establishing captions during the flight */}
165	      <AnimatePresence>
166	        {phase === "flying" && (
167	          <motion.div key="bars" className="pointer-events-auto absolute inset-0 z-[45]" initial={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: 0.5 }}>
168	            <motion.div className="absolute inset-x-0 top-0 h-[12%] bg-black" initial={{ y: "-100%" }} animate={{ y: 0 }} exit={{ y: "-100%" }} transition={{ duration: 0.6 }} />
169	            <motion.div className="absolute inset-x-0 bottom-0 h-[12%] bg-black" initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} transition={{ duration: 0.6 }} />
170	            <AnimatePresence mode="wait">
171	              {cap && (
172	                <motion.div
173	                  key={caption}
174	                  className="absolute left-6 bottom-[15%]"
175	                  initial={{ opacity: 0, x: -16 }}
176	                  animate={{ opacity: 1, x: 0 }}
177	                  exit={{ opacity: 0, x: 16 }}
178	                  transition={{ duration: 0.5 }}
179	                >
180	                  <p className="text-[12px] font-bold tracking-[0.3em] text-teal uppercase">{cap.kicker}</p>
181	                  <p className="font-display mt-1 text-[52px] leading-none text-ink uppercase drop-shadow-[0_4px_20px_rgba(0,0,0,0.8)]">{cap.title}</p>
182	                  <div className="sunset-rule mt-2 w-40" />
183	                </motion.div>
184	              )}
185	            </AnimatePresence>
186	            <button
187	              type="button"
188	              onClick={() => map.current?.skipIntro()}
189	              className="absolute right-4 bottom-[3%] min-h-[44px] min-w-[64px] px-3 text-[12px] font-bold tracking-[0.14em] text-ink/70 rounded-full"
190	            >
191	              Skip ›
192	            </button>
193	          </motion.div>
194	        )}
195	      </AnimatePresence>
196	    </>
197	  );
198	}
199	
200	const CARDS = [
201	  { src: "/loading/middlesex.webp", place: "Middlesex College", area: "Mustang City" },
202	  { src: "/loading/university-college.webp", place: "University College", area: "Mustang City" },
203	  { src: "/loading/campus.webp", place: "Western campus at dusk", area: "Forest State" },
204	];
205	
206	/** Loading art: one postcard at a time, slow push-in, cross-fade every 5 s (static for reduced motion). */
207	function Postcards() {
208	  const [i, setI] = useState(0);
209	  useEffect(() => {
210	    const t = setInterval(() => setI((n) => (n + 1) % CARDS.length), 5200);
211	    return () => clearInterval(t);
212	  }, []);
213	  const c = CARDS[i];
214	  return (
215	    <div className="absolute inset-0" aria-hidden>
216	      <AnimatePresence>
217	        <motion.div
218	          key={c.src}
219	          className="absolute inset-0 bg-cover bg-center motion-reduce:!transform-none"
220	          style={{ backgroundImage: `url(${c.src})` }}
221	          initial={{ opacity: 0, scale: 1.12, x: i % 2 ? -12 : 12 }}
222	          animate={{ opacity: 1, scale: 1.02, x: 0 }}
223	          exit={{ opacity: 0 }}
224	          transition={{ opacity: { duration: 1.2 }, scale: { duration: 7, ease: "linear" }, x: { duration: 7, ease: "linear" } }}
225	        />
226	      </AnimatePresence>
227	      <motion.p
228	        key={c.place}
229	        className="absolute left-6 text-[12px] font-medium text-ink/70"
230	        style={{ top: "calc(var(--safe-top) + 18px)" }}
231	        initial={{ opacity: 0, y: -4 }}
232	        animate={{ opacity: 1, y: 0 }}
233	        transition={{ duration: 0.6 }}
234	      >
235	        <span className="text-gold">Visit</span> {c.place} · {c.area}
236	      </motion.p>
237	    </div>
238	  );
239	}
240	
241	/** Ryan's cover art: a full collage with a slow push-in, or comic panels cycled like the postcards. */
242	function CoverArtLayer({ cover }: { cover: NonNullable<CoverArt> }) {
243	  const srcs = cover.kind === "collage" ? [cover.src] : cover.srcs;
244	  const [i, setI] = useState(0);
245	  useEffect(() => {
246	    if (srcs.length < 2) return;
247	    const t = setInterval(() => setI((n) => (n + 1) % srcs.length), 4200);
248	    return () => clearInterval(t);
249	  }, [srcs.length]);
250	  return (
251	    <div className="absolute inset-0" aria-hidden>
252	      <AnimatePresence>
253	        <motion.div
254	          key={srcs[i]}
255	          className="absolute inset-0 bg-cover bg-center motion-reduce:!transform-none"
256	          style={{ backgroundImage: `url(${srcs[i]})` }}
257	          initial={{ opacity: 0, scale: cover.kind === "collage" ? 1.08 : 1.14, rotate: cover.kind === "panels" ? (i % 2 ? -1.5 : 1.5) : 0 }}
258	          animate={{ opacity: 1, scale: 1.0, rotate: 0 }}
259	          exit={{ opacity: 0 }}
260	          transition={{ opacity: { duration: 0.9 }, scale: { duration: cover.kind === "collage" ? 14 : 6, ease: "linear" }, rotate: { duration: 6 } }}
261	        />
262	      </AnimatePresence>
263	    </div>
264	  );
265	}
