21	  logo: { file: art("scripts/cover/logo.webp"), knockout: true }, // near-black backdrop becomes transparent
22	  campus: art("public/loading/campus.webp"),
23	  uc: art("public/loading/university-college.webp"),
24	  middlesex: art("public/loading/middlesex.webp"),
25	};
26	
27	const cache = new Map();
28	/** Loads an IMG entry as { uri, width, height }. */
29	async function load(src) {
30	  const key = typeof src === "string" ? src : JSON.stringify(src);
31	  if (cache.has(key)) return cache.get(key);
32	  const { file, crop, knockout } = typeof src === "string" ? { file: src } : src;
33	  let img = sharp(readFileSync(file));
34	  if (crop) img = img.extract(crop);
35	  const { data, info } = await img.ensureAlpha().raw().toBuffer({ resolveWithObject: true });
36	  if (knockout) {
37	    // Alpha from brightness, so the logo's almost-black square fades into the black gutter.
38	    for (let i = 0; i < data.length; i += 4) {
39	      const m = Math.max(data[i], data[i + 1], data[i + 2]);
40	      data[i + 3] = Math.max(0, Math.min(255, (m - 22) * 6));
41	    }
42	  }
43	  const png = await sharp(data, { raw: info }).png().toBuffer();
44	  const out = { uri: `data:image/png;base64,${png.toString("base64")}`, width: info.width, height: info.height };
45	  cache.set(key, out);
46	  return out;
47	}
48	
49	const GUTTER = "#000000";
