        height: `${box.h * 100}%`,
        aspectRatio: box.aspect,
        left: `${box.cx * 100}%`,
        transform: "translateX(-50%)",
        WebkitMask: mask,
        mask,
        mixBlendMode: "screen",
      }}
    >
      <motion.div
        className="absolute inset-y-[-20%] w-[38%]"
        style={{ background: "linear-gradient(100deg, transparent 0%, rgba(255,240,210,0.0) 20%, rgba(255,240,210,0.85) 50%, rgba(255,240,210,0) 80%, transparent 100%)", rotate: 12 }}
