    <feFlood flood-color="#000" flood-opacity="0.9"/>
    <feComposite in2="drop" operator="in" result="dropDark"/>
    <feMerge><feMergeNode in="haloDark"/><feMergeNode in="dropDark"/><feMergeNode in="SourceGraphic"/></feMerge>
