"use client";
/**
 * The title-screen cover as a camera move, run on the compositor (Web Animations on `transform`/`opacity`),
 * so the Mapbox load happening underneath can't stutter it.
 *
 *   open  → fade in on a close-up of the Goose boss
 *   pull  → smooth ease-in-out pull back to the whole cover
 *   idle  → slow breathing around the logo
 *   dive  → accelerate into the Mustang City logo (the white flash and map flight take over from there)
 *
 * Shots are "put this point of the cover at this spot on screen, at this zoom", clamped so the scaled cover
 * always fills the screen (no black edges at any step).
 */
import { useEffect, useRef, useState } from "react";
import { LogoGlint } from "./TitleFx";

const IMG_W = 1080;
const IMG_H = 1920;
/** Points in cover-image pixels (scripts/build-cover.mjs portrait layout). */
const GOOSE = { x: 270, y: 260 };
export const COVER_LOGO = { x: 540, y: 700, h: 640, aspect: 0.825 };

export const DIVE_MS = 950;

type Shot = { p: { x: number; y: number }; s: number; at?: { x: number; y: number } };

function cameraTransform(el: HTMLElement, shot: Shot) {
  const W = el.clientWidth;
  const H = el.clientHeight;
  // background-size: cover, centred
  const k = Math.max(W / IMG_W, H / IMG_H);
  const ox = (W - IMG_W * k) / 2;
  const oy = (H - IMG_H * k) / 2;
  const P = { x: ox + shot.p.x * k, y: oy + shot.p.y * k };
  const C = shot.at ?? P; // default: the point stays where it is on screen (zoom "into" it)
  let tx = C.x - shot.s * P.x;
  let ty = C.y - shot.s * P.y;
  // keep the scaled cover covering the screen
  tx = Math.min(-shot.s * ox, Math.max(W - shot.s * (ox + IMG_W * k), tx));
  ty = Math.min(-shot.s * oy, Math.max(H - shot.s * (oy + IMG_H * k), ty));
  return `translate(${tx.toFixed(2)}px, ${ty.toFixed(2)}px) scale(${shot.s})`;
}

export default function CoverCamera({ src, dive }: { src: string; dive: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  const [loaded, setLoaded] = useState(false);
  const [idle, setIdle] = useState(false);

  // Hold everything until the cover has downloaded, or the move plays out behind a black screen.
  useEffect(() => {
    const img = new Image();
    img.onload = img.onerror = () => setLoaded(true);
    img.src = src; // onload also fires for a cached image
  }, [src]);

  // Open → pull back → breathe.
  useEffect(() => {
    const el = ref.current;
    if (!el || !loaded || dive) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const full = cameraTransform(el, { p: COVER_LOGO, s: 1 });
    if (reduce) {
      el.style.transform = full;
      el.style.opacity = "1";
      return;
    }
    const W = el.clientWidth;
    const H = el.clientHeight;
    const open = cameraTransform(el, { p: GOOSE, s: 2, at: { x: W * 0.5, y: H * 0.4 } });
    const breathe = cameraTransform(el, { p: COVER_LOGO, s: 1.035 });

    const fade = el.animate([{ opacity: 0, transform: open }, { opacity: 1, transform: open }], { duration: 450, fill: "forwards", easing: "ease-out" });
    const pull = el.animate([{ transform: open }, { transform: full }], {
      duration: 2600,
      delay: 1000, // fade + a beat on the Goose
      fill: "forwards",
      easing: "cubic-bezier(0.65, 0, 0.35, 1)",
    });
    let loop: Animation | null = null;
    pull.onfinish = () => {
      loop = el.animate([{ transform: full, opacity: 1 }, { transform: breathe, opacity: 1 }], {
        duration: 7000,
        iterations: Infinity,
        direction: "alternate",
        easing: "ease-in-out",
      });
      setIdle(true);
    };
    return () => {
      // Freeze wherever the camera is, so the dive starts from there with no jump.
      const now = getComputedStyle(el).transform;
      fade.cancel();
      pull.cancel();
      loop?.cancel();
      el.style.transform = now;
      el.style.opacity = "1";
    };
  }, [loaded, dive]);

  // Dive into the logo: keep the logo fixed on screen and zoom through it, accelerating smoothly.
  useEffect(() => {
    const el = ref.current;
    if (!el || !dive) return;
    const from = getComputedStyle(el).transform;
    const to = cameraTransform(el, { p: COVER_LOGO, s: 5 });
    const a = el.animate([{ transform: from === "none" ? cameraTransform(el, { p: COVER_LOGO, s: 1 }) : from, opacity: 1 }, { transform: to, opacity: 1 }], {
      duration: DIVE_MS,
      fill: "forwards",
      easing: "cubic-bezier(0.55, 0, 0.9, 0.35)",
    });
    return () => a.cancel();
  }, [dive]);

  return (
    <div className="absolute inset-0 overflow-hidden bg-black" aria-hidden>
      <div
        ref={ref}
        className="absolute inset-0 bg-cover bg-center will-change-transform"
        style={{ backgroundImage: `url(${src})`, transformOrigin: "0 0", opacity: 0 }}
      >
        {idle && !dive && (
          <LogoGlint box={{ cx: COVER_LOGO.x / IMG_W, cy: COVER_LOGO.y / IMG_H, h: COVER_LOGO.h / IMG_H, aspect: COVER_LOGO.aspect }} />
        )}
      </div>
    </div>
  );
}

