/** Where the Mustang City logo sits in the portrait collage (scripts/build-cover.mjs PORTRAIT_LOGO: centre 540,700 of 1080×1920). */
const LOGO_ORIGIN = "50% 36.46%";
/** Same logo as fractions of the cover's height (centre 700/1920, 640 px tall, trimmed aspect 0.825). */
const COVER_LOGO_BOX = { cx: 0.5, cy: 700 / 1920, h: 640 / 1920, aspect: 0.825 };
/** Opening close-up: the Goose boss panel (top-left of the collage). */
const OPEN_ORIGIN = "22% 6%";
export const COVER_DIVE_MS = 1150;

/**
 * Ryan's cover art. A collage opens on a close-up of one panel, pulls back to reveal the whole fragmented cover,
 * and on enter dives into the Mustang City logo. Separate panels cycle like the postcards.
 */
function CoverArtLayer({ cover, dive }: { cover: NonNullable<CoverArt>; dive: boolean }) {
  const srcs = cover.kind === "collage" ? [cover.src] : cover.srcs;
  const [i, setI] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const [loaded, setLoaded] = useState(false);
  // Hold the pull-back until the collage has downloaded, or it plays out behind a black screen.
  useEffect(() => {
    if (cover.kind !== "collage") return;
    const img = new Image();
    img.onload = img.onerror = () => setLoaded(true);
    img.src = cover.src; // onload also fires for a cached image
  }, [cover]);
  useEffect(() => {
    if (srcs.length < 2) return;
    const t = setInterval(() => setI((n) => (n + 1) % srcs.length), 4200);
    return () => clearInterval(t);
  }, [srcs.length]);

  if (cover.kind === "collage") {
    // Scale 1 is the hand-off point: changing transform-origin there causes no jump. Once revealed, the cover
    // "breathes" around the logo so the title screen never sits dead still; the dive takes over from wherever it is.
    const target = dive
      ? { scale: 7, opacity: 1, transformOrigin: LOGO_ORIGIN }
      : !loaded
        ? { scale: 2.1, opacity: 0, transformOrigin: OPEN_ORIGIN }
        : revealed
          ? { scale: [1, 1.035, 1], opacity: 1, transformOrigin: LOGO_ORIGIN }
          : { scale: 1, opacity: 1, transformOrigin: OPEN_ORIGIN };
    const transition = dive
      ? { scale: { duration: COVER_DIVE_MS / 1000, ease: [0.7, 0, 0.84, 0] as const } }
      : revealed
        ? { scale: { duration: 14, ease: "easeInOut" as const, repeat: Infinity } }
        : { scale: { duration: 3.4, ease: [0.16, 1, 0.3, 1] as const, delay: 0.5 }, opacity: { duration: 0.6 } };
    return (
      <div className="absolute inset-0 bg-black" aria-hidden>
        <motion.div
          className="absolute inset-0 bg-cover bg-center motion-reduce:!transform-none"
          style={{ backgroundImage: `url(${cover.src})` }}
          initial={{ scale: 2.1, opacity: 0, transformOrigin: OPEN_ORIGIN }}
          animate={target}
          onAnimationComplete={() => loaded && !dive && !revealed && setRevealed(true)}
          transition={transition}
        >
          {revealed && !dive && <LogoGlint box={COVER_LOGO_BOX} />}
        </motion.div>
      </div>
    );
  }

  return (
    <div className="absolute inset-0" aria-hidden>
      <AnimatePresence>
        <motion.div
          key={srcs[i]}
          className="absolute inset-0 bg-cover bg-center motion-reduce:!transform-none"
          style={{ backgroundImage: `url(${srcs[i]})` }}
          initial={{ opacity: 0, scale: 1.14, rotate: i % 2 ? -1.5 : 1.5 }}
          animate={{ opacity: 1, scale: 1.0, rotate: 0 }}
          exit={{ opacity: 0 }}
          transition={{ opacity: { duration: 0.9 }, scale: { duration: 6, ease: "linear" }, rotate: { duration: 6 } }}
        />
      </AnimatePresence>
    </div>
  );
}

