// Dense game-cover grid: panels tile the whole frame (no empty band), alternating gutter slopes, and the logo
// sits on top of them. Logo centre/height are mirrored in components/Intro.tsx (LOGO_ORIGIN, COVER_LOGO_BOX).
export const PORTRAIT_LOGO = { cx: 540, cy: 700, h: 640 };

async function portrait() {
  const W = 1080, H = 1920;
  // Row gutters: (0,690)→(1080,640) and (0,1290)→(1080,1340). Column gutters slant the other way per row.
  const body = [
    await panel("p1", IMG.gooseBoss, [[0, 0], [590, 0], [560, 664], [0, 690]], [0.4, 0.05]),
    await panel("p2", IMG.middlesex, [[590, 0], [1080, 0], [1080, 640], [560, 664]], [0.62, 0.15]),
    await panel("p3", IMG.gas, [[0, 690], [600, 662], [650, 1320], [0, 1290]], [0.5, 0.7]),
    await panel("p4", IMG.delilahs, [[600, 662], [1080, 640], [1080, 1340], [650, 1320]], [0.5, 0.45]),
    await panel("p5", IMG.bus, [[0, 1290], [470, 1312], [430, 1920], [0, 1920]], [0.3, 0.5]),
    await panel("p6", IMG.gooseAttack, [[470, 1312], [1080, 1340], [1080, 1920], [430, 1920]], [0.5, 0.55]), // bottom row: nothing covers the faces
