export type Celebration = { id: string; kind: "rank" | "badge" | "district" | "ride" | "collectible" | "class"; title: string; subtitle: string; color?: string; glyph?: string };

let queue: Celebration[] = [];
const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());

export function celebrate(c: Celebration) {
  if (queue.length >= 4 || queue.some((q) => q.id === c.id)) return; // don't flood
  queue = [...queue, c];
  emit();
}

export function dismissCelebration() {
  queue = queue.slice(1);
  emit();
}

