      {/* Faculty turf */}
      <div className="hud-panel flex items-center gap-3 px-4 py-3">
        <span className="h-8 w-8 shrink-0 rounded-lg" style={{ background: holder ? facultyColor(holder.faculty) : "rgba(255,255,255,0.08)" }} aria-hidden />
