for (const k of ["Region side quests + map blips", "First-run coach marks", "Near-miss nudges", "Wanted level", "Variable rewards on pass", "Pause-screen music", "The Goose calls you", "Photo mode", "Live big-screen mirror", "Stash & carry"])
  b = b.replace(`- [ ] **${k}`, `- [x] **${k}`);
