const fs = require("fs");
function edit(f, pairs) { const raw = fs.readFileSync(f, "utf8"); const crlf = raw.includes("\r\n"); let t = raw.replace(/\r\n/g, "\n");
  for (const [a, b] of pairs) { if (!t.includes(a)) throw new Error(f + " missing: " + a.slice(0, 60)); t = t.replace(a, b); }
  fs.writeFileSync(f, crlf ? t.replace(/\n/g, "\r\n") : t); }
// Surprise payout: store multiplier at reach time (value = Rep earned) so Rep stays stable after the event ends.
edit("lib/progress.ts", [
  ['import { SURPRISE_REP, surpriseAt } from "./surprise";', 'import { SURPRISE_REP, surpriseAt } from "./surprise";\nimport { currentEvent } from "./season";'],
  ["  surprises?: Record<string, number>; // surprise blip id (`${day}:${i}`) → reached at\n", "  surprises?: Record<string, number>; // surprise blip id (`${day}:${i}`) → reached at\n  surpriseRep?: Record<string, number>; // surprise id → Rep earned (seasonal events can pay double)\n"],
  [`      data.surprises = { ...(data.surprises ?? {}), [surprise.id]: Date.now() };
      celebrate({ id: \`surprise-\${surprise.id}\`, kind: "surprise", title: \`Surprise: \${surprise.name}\`, subtitle: \`Found before midnight · +\${SURPRISE_REP} Rep\`,`,
   `      const ev = currentEvent();
      const earned = SURPRISE_REP * (ev?.surpriseMultiplier ?? 1);
      data.surprises = { ...(data.surprises ?? {}), [surprise.id]: Date.now() };
      data.surpriseRep = { ...(data.surpriseRep ?? {}), [surprise.id]: earned };
      celebrate({ id: \`surprise-\${surprise.id}\`, kind: "surprise", title: \`Surprise: \${surprise.name}\`, subtitle: \`Found before midnight · +\${earned} Rep\${ev ? \` (\${ev.name})\` : ""}\`,`],
  ["    const surpriseRep = Object.keys(data.surprises ?? {}).length * SURPRISE_REP;", "    const surpriseRep = Object.keys(data.surprises ?? {}).reduce((s, id) => s + (data.surpriseRep?.[id] ?? SURPRISE_REP), 0);"],
  ["        surprises: parsed.surprises ?? {},", "        surprises: parsed.surprises ?? {},\n        surpriseRep: parsed.surpriseRep ?? {},"],
  ["sideDone: {}, bag: [], stash: [], surprises: {} };", "sideDone: {}, bag: [], stash: [], surprises: {}, surpriseRep: {} };"],
]);
